      "claim": "The motorway vignette is valid from 1 December of the previous year to 31 January of the following year, i.e. up to 14 months",
      "verdict": "contradicted"
    },
    {
      "claim": "There are no short-term (daily, weekly, 10-day) vignettes: the National Roads Charge Act does not provide for them",
      "verdict": "contradicted"
    },
    {
      "claim": "The e-vignette is valid immediately after purchase",
      "verdict": "unverifiable"
    },
    {
      "claim": "In Switzerland, the vignette is exclusively available as an annual vignette",
      "verdict": "supported"
    },
    {
      "claim": "Other countries, such as Austria, offer various vignettes including 10-day vignettes, two-month vignettes, or weekly vignettes",
      "verdict": "unverifiable"
    }
